package org.lwjgl.opengl;import org.joml.Matrix4f;import java.util.*;public class GL11{public static final int GL_BLEND=1,GL_SRC_ALPHA=2,GL_ONE_MINUS_SRC_ALPHA=3,GL_CULL_FACE=4,GL_MODELVIEW=5;public static Matrix4f matrix=new Matrix4f();static final Deque<Matrix4f> stack=new ArrayDeque<>();public static void reset(){matrix.identity();stack.clear();}public static void glPushMatrix(){stack.push(new Matrix4f(matrix));}public static void glPopMatrix(){matrix=stack.pop();}public static void glTranslated(double x,double y,double z){matrix.translate((float)x,(float)y,(float)z);}public static void glScaled(double x,double y,double z){matrix.scale((float)x,(float)y,(float)z);}public static void glScalef(float x,float y,float z){matrix.scale(x,y,z);}public static void glRotated(double deg,double x,double y,double z){matrix.rotate((float)Math.toRadians(deg),(float)x,(float)y,(float)z);}public static void glRotatef(float deg,float x,float y,float z){glRotated(deg,x,y,z);}public static void glEnable(int v){}public static void glDisable(int v){}public static void glBlendFunc(int x,int y){}public static void glMatrixMode(int m){}}
